import { test, expect } from '@playwright/test';

test.describe('Notification Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should navigate to relevant content when clicking a notification', async ({ page }) => {
    // Verify notifications page is loaded
    const notificationsList = page.getByRole('list', { name: /notifications/i });
    await expect(notificationsList).toBeVisible();

    // Verify notification items are visible
    const notificationItems = page.getByRole('listitem');
    await expect(notificationItems).toHaveCount(3);

    // Click on a notification to navigate to the relevant content
    const firstNotification = page.getByRole('listitem').first();
    await firstNotification.click();

    // Verify navigation to the content page
    await expect(page).toHaveURL(/.*\/content\/123/);
    await expect(page.getByRole('heading', { name: /notification content/i })).toBeVisible();

    // Verify notification details are displayed
    const notificationTitle = page.getByText('New feature released');
    await expect(notificationTitle).toBeVisible();
  });

  test('should handle notification with no associated content gracefully', async ({ page }) => {
    // Verify notifications page is loaded
    const notificationsList = page.getByRole('list', { name: /notifications/i });
    await expect(notificationsList).toBeVisible();

    // Click on a notification that has no associated content
    const noContentNotification = page.getByRole('listitem', { name: /no content/i });
    await noContentNotification.click();

    // Verify user is on the notifications page
    await expect(page).toHaveURL(/.*\/notifications/);
    await expect(page.getByRole('heading', { name: /notifications/i })).toBeVisible();

    // Verify a message is displayed when no content is available
    const noContentMessage = page.getByText(/no content available/i);
    await expect(noContentMessage).toBeVisible();

    // Verify the notification is still visible
    await expect(noContentNotification).toBeVisible();
  });
});
